  const differing = execFileSync("git", ["diff", "--name-only", stable], { cwd: work, encoding: "utf8" }).trim();
  if (differing) fail(`stable commit differs from RC + sync-version ${stablePackage.version} in: ${differing.split("\n").join(", ")}`);
